export const ICON_BY_ID = Object.fromEntries(ICONS.map((i) => [i.id, i]))

const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
// ícone salvo ("icone:<id>") -> objeto do ícone (undefined se vazio, desconhecido ou "sem ícone")
export const iconOf = (logo) => String(logo || '').startsWith(ICON_PREFIX) ? ICON_BY_ID[String(logo).slice(ICON_PREFIX.length)] : undefined
// sugere um ícone pelo nome da conta (palavra inteira; vence o apelido mais longo)
export function suggestIcon(name) {
  const n = ` ${norm(name)} `
  let best = null, len = 0
  ICONS.forEach((i) => [i.nome, ...i.apelidos].forEach((a) => {
    const k = norm(a)
    if (k && k.length > len && n.includes(` ${k} `)) { best = i; len = k.length }
  }))
  return best
}
// texto/ícone claro sobre fundo escuro e vice-versa
export function glyphColor(hex) {
  const h = String(hex || DEFAULT_COLOR).replace('#', '')
  const v = h.length === 3 ? h.split('').map((c) => c + c).join('') : h
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(v.slice(i, i + 2), 16) || 0)
  return 0.299 * r + 0.587 * g + 0.114 * b > 170 ? '#1a1a1a' : '#ffffff'
}
